 add('Corregimos el diseño y conservamos los resultados reales',cards([('51','Criterios API trazados','G4 y núcleo común; diseño y ejecución separados.'),('60','Escenarios web definidos','54 previos + 6 del núcleo, en archivos .feature ejecutables.'),('3','Perfiles completos de rendimiento','Carga, campaña y estrés identificados por run.')])+paragraph('No modificamos Qolqe ni convertimos defectos conocidos en pruebas aprobadas.')+link('../../docs/final/requerimientos-y-umbrales.md','Alcance, supuestos y criterios'),'ALCANCE')
 add('Una arquitectura, responsabilidades separadas','<div class="flow"><span>Requisitos HU/CA</span><b>→</b><span>Casos y Gherkin</span><b>→</b><span>Ejecutores</span><b>→</b><span>Qolqe real</span></div><div class="flow"><span>Resultados crudos</span><b>→</b><span>Gates</span><b>→</b><span>Matriz por corrida</span><b>→</b><span>Reporte visible</span></div>'+paragraph('Datos y bases aislados · Fuentes identificadas · Python/FastAPI/SQLite intactos')+link('../../docs/final/arquitectura-y-patrones.md','Arquitectura y decisiones'),'ARQUITECTURA')
 add('Las herramientas se complementan',table(['Herramienta','Qué comprueba','Qué no sustituye'],[['Karate','Reglas, estados, efectos y contratos explícitos','Interacción visual'],['Schemathesis','Señales generadas desde OpenAPI, al inicio','Casos funcionales diseñados'],['Cypress + Cucumber','Escenarios web y persistencia','Autorización de todos los endpoints'],['k6 + Python','Carga HTTP, recursos y conciliación','Capacidad certificada de producción']])+paragraph('Elegimos por adecuación al alcance. No ejecutamos un benchmark entre herramientas.')+link('../../docs/final/arquitectura-y-patrones.md','Comparación y costos'),'HERRAMIENTAS')
 add('API: cubrir un requisito no equivale a aprobarlo',cards([('136','Identificadores API','116 base + 5 complementarios + 15 técnicos.'),('187','Escenarios y variantes','Outlines expandidos; resultado verificado por ejecución.'),('51','Criterios del requerimiento','G4 y núcleo común; funcionales y técnicos complementarios.')])+paragraph('Schemathesis explora contactos y solicitudes. Sus checks no se suman como casos funcionales ni defectos únicos.')+report_link+link('../../API/features/contrato-nucleo-solicitudes.feature','Código técnico adicional'),'API')
