 add('POM: mantenimiento hoy, crecimiento controlado',table(['Patrón','Ventaja','Decisión'],[['POM + componentes','Selectores y acciones por pantalla','Elegido para nuestro tamaño y equipo'],['Screenplay','Actores y tareas transversales','Evaluar al crecer roles y procesos'],['Scripts directos','Inicio rápido','Mayor duplicación al cambiar la UI']])+paragraph('Escenarios conservan oráculos; fixtures preparan datos. Para paralelizar hacen falta instancias y relojes separados, no solo más procesos.')+link('../../Web/cypress/pages/ContactosPage.ts','Page Object')+link('../../docs/final/arquitectura-y-patrones.md','Justificación y escalabilidad'),'PATRÓN')
