 add('Rendimiento: del negocio a criterios medibles',table(['Requerimiento','Modelo / criterio'],[['3000 sesiones/h × 2 min','≈100 VUs; campaña ≈300'],['6 operaciones por sesión','≥5 operaciones correctas/s en hora punta; login aparte'],['Consultas / dinero','p95 <800 ms / <1500 ms por operación'],['Error / integridad','≤1% normal; cero duplicados o parciales detectados'],['Pausas y rampa','10–25 s, media 18; campaña sube en 300 s']])+paragraph('Ventanas estables separadas del arranque. Resistencia de 18 h relevante, no ejecutada.')+link('../../docs/final/requerimientos-y-umbrales.md','Derivación y límites'),'RENDIMIENTO')
 load=by['carga'];campaign=by['campana'];stress=by['estres']
