 levels=[25,50,100,200,300,450,600];svg='<svg viewBox="0 0 900 300" role="img" aria-label="Operaciones exitosas por segundo por escalón de usuarios">'
 for i,(n,w)in enumerate(zip(levels,stress['windows'])):
  x=50+i*120;h=w['ops_s']/18*210;color='#28745e'if w.get('per_operation_ok')else'#af593f'
